// Levantamiento documental y de código. Sin acceso ni escrituras a sistemas remotos.
export const groups = {Backend: [], Frontend: [], Integraciones: [], Servicios: []};
const seq = {};
function add(area,module,title,scope,status,gap,complexity,reason,priority,deps,actor,want,benefit,criteria,source,nature='Derivado del alcance') {
 const prefix={Backend:'BE',Frontend:'FE',Integraciones:'INT',Servicios:'SER'}[area];
 const id=`${prefix}-${String(seq[area]=(seq[area]||0)+1).padStart(3,'0')}`;
 groups[area].push([id,module,title,scope,nature,status,gap,complexity,reason,priority,deps,`Como ${actor}, quiero ${want} para ${benefit}.`,criteria,source,'Pendiente']);
}
